    "question": "Câu 27: Bạn là quản trị viên mạng cho một công ty trong danh sách Fortune 500. Bạn chịu trách nhiệm cho tất cả các máy tính khách tại cơ sở trung tâm. Bạn muốn đảm bảo rằng tất cả các máy tính khách đều có phần mềm mới nhất được cài đặt cho hệ điều hành của chúng, bao gồm phần mềm trong các danh mục Cập nhật Quan trọng và Gói Dịch vụ, Dòng Windows Server 2012 R2, và Cập nhật Trình điều khiển. Bạn muốn tự động hóa quy trình càng nhiều càng tốt, và bạn muốn các máy tính khách tải xuống các bản cập nhật từ một máy chủ trung tâm mà bạn đang quản lý. Bạn quyết định sử dụng Windows Server Update Services (WSUS). Phần mềm máy chủ WSUS đã được cài đặt trên một máy chủ có tên là WSUSServer. Bạn muốn kiểm tra máy chủ WSUS trước khi thiết lập các chính sách nhóm trong miền. Bạn cài đặt Windows 8. Cần phải thực hiện mục đăng ký nào sau đây để máy khách chỉ định rằng nó nên sử dụng WSUSServer cho Windows Update?",
