    "question": "Câu 27: Bạn là quản trị viên mạng cho một miền Active Directory lớn có tên là Panek.com. Miền này chứa một máy chủ có tên là Saturn chạy Windows Server 2012 R2. Saturn đã cài đặt vai trò Máy chủ DHCP. Mạng chứa 400 máy tính khách chạy Windows 7 và Windows\n8. Tất cả các máy tính khách đều được tham gia vào miền và được cấu hình là máy khách DHCP. Bạn cài đặt một máy chủ mới có tên là Jupiter chạy Windows Server 2012 R2. Trên Jupiter, bạn cài đặt dịch vụ vai trò Máy chủ Chính sách Mạng (NPS) và bạn cấu hình Bảo vệ Truy cập Mạng (NAP) để sử dụng phương pháp thực thi DHCP. Bạn cần đảm bảo rằng Saturn chỉ cung cấp một cổng mặc định hợp lệ cho các máy tính vượt qua xác thực tình trạng hệ thống. Bạn nên thực hiện hai hành động nào?\n1. Từ bảng điều khiển DHCP, cấu hình tùy chọn 016 Swap Server.\n2. Từ bảng điều khiển DHCP, bật NAP trên tất cả các phạm vi.\n3. Từ bảng điều khiển Cấu hình Máy khách NAP, bật máy khách Thực thi Cách ly DHCP.\n4. Từ bảng điều khiển DHCP, tạo một chính sách mới.\n5. Từ Trình quản lý Máy chủ, cài đặt dịch vụ vai trò Máy chủ Chính sách Mạng.",
