    "question": "Câu 30: Bạn là quản trị viên mạng cho một công ty có hai văn phòng; một ở Bờ Đông và một ở Bờ Tây. Thông tin bán hàng cần được gửi từ văn phòng Bờ Đông đến văn phòng Bờ Tây một cách thường xuyên, và một số thông tin về lương và báo cáo kế toán cần được gửi trở lại Bờ Đông. Chủ sở hữu của công ty bạn đã đọc những câu chuyện trên báo về các vấn đề bảo mật trên Internet và từ chối cho phép bất kỳ thông tin nào của công ty đi qua Internet, bất kể bạn nói bao nhiêu về việc bảo mật các đường truyền đó. Việc liên lạc giữa các trang web diễn ra khoảng một lần một tuần. Bạn sẽ thực hiện các bước nào để đảm bảo xác thực an toàn và truyền tải an toàn mà không tốn quá nhiều tiền?\n1. Cấu hình PAP làm phương thức xác thực giữa các máy chủ.\n2. Cài đặt RRAS trên một máy chủ ở mỗi địa điểm và giữ cho đường dây luôn mở bằng kết nối ISDN sẽ luôn có sẵn để liên lạc.\n3. Cài đặt RRAS trên một máy chủ ở mỗi địa điểm và cấu hình quay số theo yêu cầu để mở kết nối mỗi khi có đường truyền.\n4. Cấu hình CHAP làm phương thức xác thực giữa các máy chủ.\n5. Cấu hình MS-CHAPv2 làm phương thức xác thực giữa các máy chủ.\n6. Cấu hình IPsec làm phương thức mã hóa giữa các máy chủ.\n7. Cấu hình MPPE làm phương thức mã hóa giữa các máy chủ.\n8. Cấu hình L2TP làm phương thức mã hóa giữa các máy chủ.",
