      "B. Sử dụng HKEY_LOCAL_MACHINE\\Software\\Policies\\Microsoft\\Windows\\WindowsUpdate\\AU\\UseWUSer ver và chỉ định 1 cho dữ liệu. Sử dụng HKEY_LOCAL_MACHINE\\Software\\Policies\\Microsoft\\Windows\\WindowsUpdate\\WUServer và chỉ định http: //WSUSServer.",
