    "question": "Crystal là một quản trị viên hệ thống cho một môi trường Active Directory đang chạy ở chế độ Gốc (Native mode). Gần đây, một số người quản lý đã báo cáo những nghi ngờ về hoạt động của người dùng và đã yêu cầu cô ấy tăng cường bảo mật trong môi trường. Cụ thể, các yêu cầu như sau: Việc truy cập một số tệp nhạy cảm phải được ghi lại. Việc sửa đổi một số tệp nhạy cảm phải được ghi lại. Các quản trị viên hệ thống phải có khả năng cung cấp thông tin về những người dùng đã truy cập các tệp nhạy cảm và thời điểm họ truy cập. Tất cả các lần thử đăng nhập cho các máy dùng chung cụ thể phải được ghi lại. Crystal nên thực hiện các bước nào sau đây để đáp ứng các yêu cầu này?\n1. Bật kiểm toán bằng công cụ Quản lý Máy tính.\n2. Bật kiểm toán bằng công cụ Người dùng và Máy tính Active Directory.\n3. Bật kiểm toán bằng công cụ Miền và Quan hệ tin cậy Active Directory.\n4. Bật kiểm toán bằng công cụ Trình xem Sự kiện.\n5. Xem nhật ký kiểm toán bằng công cụ Trình xem Sự kiện\n6. Xem thông tin kiểm toán bằng công cụ Quản lý Máy tính.\n7. Bật cài đặt kiểm toán thất bại và thành công cho các tệp cụ thể được lưu trữ trên các ổ đĩa NTFS.\n8. Bật cài đặt kiểm toán thất bại và thành công cho các sự kiện đăng nhập trên các tài khoản máy tính cụ thể",
