    "question": "Một quản trị viên hệ thống đang có kế hoạch triển khai các đối tượng Chính sách Nhóm trong môi trường Active Directory Windows Server 2012 R2 mới. Để đáp ứng nhu cầu của tổ chức, anh ấy quyết định triển khai một hệ thống phân cấp các cài đặt Chính sách Nhóm. Anh ấy có thể gán các cài đặt Chính sách Nhóm ở các cấp độ nào sau đây?\n1. Sites (Trang)\n2. Domains (Miền)\n3. Organizational units (Đơn vị tổ chức)\n4. Local system (Hệ thống cục bộ)",
