    "question": "Khởi động Thiết lập Windows Server từ đĩa cài đặt và chọn Xây dựng lại hệ thống tệp (Rebuild File System).",
    "options": [],
    "answer": "C",
    "source": "NOI DUNG ON TAP - QTHTM - 04-6-2026.pdf"
