    "question": "Trong quá trình thiết kế hệ thống tính sẵn sàng cao (High Availability) cho doanh nghiệp, bạn cần lựa chọn hệ điều hành phù hợp để triển khai tính năng Failover Clustering. Phiên bản nào sau đây của Windows Server 2012 R2 KHÔNG hỗ trợ cấu hình cụm chuyển đổi dự phòng (failover cluster)?",
