    "question": "Bạn đang thiết kế kiến trúc tính sẵn sàng cao (High Availability) cho trung tâm dữ liệu của doanh nghiệp bằng cách sử dụng tính năng Failover Clustering trên nền tảng Windows Server 2022. Theo giới hạn thiết kế của Microsoft, một cụm chuyển đổi dự phòng (f ailover cluster) duy nhất trong hệ điều hành này có thể mở rộng tối đa lên đến bao nhiêu nút (node)?",
