    "question": "Hạ tầng mạng của tổ chức bạn đang hoạt động trong một rừng Active Directory duy nhất và sử dụng máy chủ Windows Server 2022 làm Domain Controller kiêm máy chủ phân giải tên miền chính (DNS Server). Gần đây, phòng kỹ thuật triển khai thêm một máy chủ DNS chạy trên nền tảng Linux/Unix (sử dụng BIND) để phân tải dự phòng ở cùng một trung tâm dữ liệu. Để máy chủ Windows DNS có thể thực hiện quá trình chuyển giao vùng (zone transfer) dữ liệu bản ghi sang máy chủ DNS dựa trên Unix một cách tương thích mà không gặp lỗi giải mã, bạn cần phải thực hiện thao tác cấu hình nào?",
