    "question": "Bạn là kiến trúc sư hệ thống mạng cho một tập đoàn vừa trải qua quá trình sáp nhập. Tập đoàn hiện đang quản lý hai miền (domain) trong rừng Active Directory: stellacon.com (công ty mẹ) và abc.com (công ty con). Do các quy định bảo mật thông tin nội bộ nghiêm ngặt, chính sách hệ thống hoàn toàn nghiêm cấm việc sao chép hoặc chuyển vùng dữ liệu DNS (DNS zone transfer) giữa hai miền này. Tuy nhiên, nhân viên thuộc nhánh abc.com lại thường xuyên cần truy cập vào các cổng thông tin nội bộ được lưu trữ tại n hánh stellacon.com. Để đảm bảo rằng mọi truy vấn tên miền từ phía người dùng abc.com nhắm đến mạng stellacon.com đều được trỏ và phân giải trực tiếp bởi các máy chủ DNS của stellacon.com, bạn nên làm gì?",
