    "question": "Bạn là quản trị viên hệ thống chuẩn bị triển khai một ứng dụng quản lý tài chính mới lên máy trạm của kế toán trưởng. Để đảm bảo an toàn, bạn cần thực hiện sao lưu toàn bộ dữ liệu hiện có. Ngoài ra, yêu cầu đặt ra là nếu trong quá trình cài đặt ứng dụng mới làm mất mát hoặc ghi đè (thay thế) các tệp tin người dùng riêng lẻ, bạn phải có khả năng khôi phục chính xác các tệp đó mà không cần phải phục hồi toàn bộ hệ điều hành. Thao tác nào dưới đây đáp ứng tốt nhất các yêu cầu trên?",
