    "question": "Bạn là quản trị viên hệ thống quản lý một hạ tầng mạng sử dụng dịch vụ DHCP trên Windows Server. Sau một thời gian dài vận hành, bạn phát hiện tệp tin cơ sở dữ liệu DHCP (dhcp.mdb) đã tăng kích thước đáng kể, gây ảnh hưởng đến hiệu suất và thời gian sao lưu hệ thống. Để tối ưu hóa và giảm kích thước tệp tin cơ sở dữ liệu này một cách an toàn thông qua công cụ dòng lệnh, bạn nên thực hiện lệnh nào dưới đây tại thư mục lưu trữ cơ sở dữ liệu?",
