    "question": "Bạn là quản trị viên hệ thống quản lý một môi trường máy chủ tập trung bao gồm nhiều máy chủ chạy hệ điều hành Windows Server mới nhất. Hiện tại, máy chủ tệp (File Server) của công ty đang gặp tình trạng ổ đĩa lưu trữ dần cạn kiệt dung lượng. Do những hạn chế về phần cứng, bạn không thể bổ sung thêm ổ đĩa vật lý mới. Để đảm bảo tính công bằng và kiểm soát được dung lượng lưu trữ tối đa mà mỗi người dùng có thể sử dụng trên hệ thống tệp tin, bạn cần triển khai cơ chế nào dưới đây?",
