    "id": "pdf_nd_168",
    "num": 169,
    "question": "Bạn là quản trị viên hệ thống tại một tập đoàn đa quốc gia có hạ tầng gồm nhiều máy chủ tệp (File Servers) chạy hệ điều hành Windows Server. Dữ liệu của người dùng thường xuyên được di chuyển hoặc sao lưu giữa các máy chủ để cân bằng tải và bảo trì. Điều này gây khó khăn cho nhân viên khi họ phải liên tục cập nhật đường dẫn (UNC path) mỗi khi tài nguyên bị thay đổi vị trí. Giải pháp nào dưới đây bạn nên triển khai để cung cấp cho người dùng một \"không gian tên\" (namespace) thống nhất, cho phép họ truy cập tài nguyên một cách xuyên suốt bất kể tệp tin thực tế đang nằm trên máy chủ nào?",
