    "question": "Bạn là chuyên viên quản trị hệ thống đang thiết lập môi trường lưu trữ tập trung cho trung tâm dữ liệu. Bạn đang cấu hình máy chủ iSCSI Target và cần mở cổng (port) trên tường lửa để cho phép các máy chủ (iSCSI Initiators) có thể kết nối và truy cập vào cá cđơn vị lưu trữ (LUNs) thông qua giao thức iSCSI. Cổng TCP mặc định nào cần được mở để đảm bảo các kết nối này được thiết lập thành công?",
